import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  repo_pitches: defineTable({
    repo: v.string(),
    pitch: v.string(),
  }),
});

import { action, internalMutation, query } from "./_generated/server";
import { v } from "convex/values";
import { internal } from "./_generated/api";
import OpenAI from "openai";

export const list = query({
  args: {},
  handler: async (ctx) => {
    return await ctx.db.query("repo_pitches").order("desc").collect();
  },
});

export const save = internalMutation({
  args: { repo: v.string(), pitch: v.string() },
  handler: async (ctx, args) => {
    await ctx.db.insert("repo_pitches", {
      repo: args.repo,
      pitch: args.pitch,
    });
  },
});

export const generate = action({
  args: { repo: v.string() },
  handler: async (ctx, args) => {
    const repoResponse = await fetch(`https://api.github.com/repos/${args.repo}`, {
      headers: {
        "User-Agent": "Convex-App",
      },
    });

    if (!repoResponse.ok) {
      throw new Error(`Failed to fetch repo data: ${repoResponse.statusText}`);
    }

    const repoData = (await repoResponse.json()) as { description: string | null };
    const description = repoData.description || "No description provided.";

    const openai = new OpenAI({
      apiKey: process.env.OPENAI_API_KEY,
    });

    const response = await openai.chat.completions.create({
      model: "gpt-3.5-turbo",
      messages: [
        {
          role: "system",
          content: "You are a marketing expert. Generate a 1-sentence promotional pitch for a GitHub repository based on its description.",
        },
        {
          role: "user",
          content: `Repository: ${args.repo}\nDescription: ${description}`,
        },
      ],
    });

    const pitch = response.choices[0].message.content?.trim() || "Could not generate pitch.";

    await ctx.runMutation(internal.pitches.save, {
      repo: args.repo,
      pitch: pitch,
    });

    return pitch;
  },
});

import { useState } from "react";
import { useQuery, useAction } from "convex/react";
import { api } from "../convex/_generated/api";
import "./App.css";

function App() {
  const [repo, setRepo] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const pitches = useQuery(api.pitches.list);
  const generatePitch = useAction(api.pitches.generate);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!repo) return;

    setIsGenerating(true);
    try {
      await generatePitch({ repo });
      setRepo("");
    } catch (error) {
      console.error("Error generating pitch:", error);
      alert("Failed to generate pitch. Make sure the repo exists and check your API keys.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="App">
      <h1>GitHub Repo Pitch Generator</h1>

      <form onSubmit={handleSubmit}>
        <input
          type="text"
          value={repo}
          onChange={(e) => setRepo(e.target.value)}
          placeholder="e.g. facebook/react"
          disabled={isGenerating}
        />
        <button type="submit" disabled={isGenerating || !repo}>
          {isGenerating ? "Generating..." : "Generate Pitch"}
        </button>
      </form>

      <section>
        <h2>Recent Pitches</h2>
        {pitches === undefined ? (
          <p>Loading pitches...</p>
        ) : pitches.length === 0 ? (
          <p>No pitches generated yet.</p>
        ) : (
          <ul>
            {pitches.map((pitch) => (
              <li key={pitch._id}>
                <strong>{pitch.repo}</strong>: {pitch.pitch}
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

export default App;

